* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 16px; background: #182321; color: #f4f0dc; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #29433b 0, #182321 68%); }
.shop { width: min(100%, 720px); padding: clamp(22px, 5vw, 40px); border: 1px solid #496454; border-radius: 20px; background: #202d29; box-shadow: 0 24px 70px #101917aa; }
.shop-header { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding-bottom: 28px; border-bottom: 1px solid #3a4d43; }
.eyebrow, .sales-label { margin: 0; color: #b9d27a; font-size: .78rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 6px 0 2px; font-size: clamp(2rem, 7vw, 3rem); line-height: 1.08; letter-spacing: -.04em; }
.subtitle { margin: 8px 0 0; color: #b9c5b7; }
.sales-card { min-width: 145px; padding: 14px 17px; border: 1px solid #52694d; border-radius: 12px; background: #29392f; text-align: right; }
.sales-card strong { display: block; margin-top: 4px; color: #e4f29e; font-size: 1.7rem; font-variant-numeric: tabular-nums; }
.section-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin: 26px 0 14px; }
h2 { margin: 0; font-size: 1.2rem; }
.stock-note { color: #b9c5b7; font-size: .9rem; }
.item-list { display: grid; gap: 10px; }
.item { display: grid; grid-template-columns: 52px minmax(0, 1fr) auto; align-items: center; gap: 14px; padding: 13px; border: 1px solid #3e5147; border-radius: 13px; background: #26342f; }
.item-icon { width: 50px; height: 50px; display: grid; place-items: center; border-radius: 11px; background: #35473a; font-size: 1.75rem; }
.item-info { min-width: 0; }
.item-name { margin: 0; font-size: 1.05rem; font-weight: 750; }
.item-meta { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 4px; color: #c2cebd; font-size: .92rem; }
.stock { color: #e4f29e; font-weight: 700; }
.stock.out { color: #f0a58d; }
.item-actions { display: flex; gap: 8px; }
button { min-height: 42px; padding: 8px 12px; border: 1px solid #b9d27a; border-radius: 9px; background: #b9d27a; color: #1b2821; font: inherit; font-size: .94rem; font-weight: 750; cursor: pointer; transition: transform .12s, background .12s, border-color .12s; }
button.restock { border-color: #637969; background: #34463c; color: #f4f0dc; }
button:hover:not(:disabled) { transform: translateY(-1px); background: #d3e69a; }
button.restock:hover:not(:disabled) { background: #43594a; border-color: #b9d27a; }
button:active:not(:disabled) { transform: translateY(1px); }
button:focus-visible { outline: 3px solid #f4f0dc; outline-offset: 3px; }
button:disabled { border-color: #59625a; background: #414a43; color: #c1c6b9; cursor: not-allowed; }
footer { margin-top: 23px; color: #9eae9f; text-align: center; font-size: .9rem; }
footer span { color: #b9d27a; }
@media (max-width: 520px) {
  body { padding: 16px 12px; }
  .shop { padding: 22px 16px; }
  .shop-header { align-items: flex-start; flex-direction: column; }
  .sales-card { width: 100%; display: flex; justify-content: space-between; align-items: center; text-align: left; }
  .sales-card strong { margin: 0; }
  .item { grid-template-columns: 46px minmax(0, 1fr); gap: 11px; padding: 11px; }
  .item-icon { width: 44px; height: 44px; }
  .item-actions { grid-column: 1 / -1; justify-content: stretch; }
  .item-actions button { flex: 1; }
  .section-heading { align-items: flex-start; flex-direction: column; gap: 4px; }
}

const items = [
  { id: "mushroom", name: "Mooncap Mushroom", icon: "🍄", price: 4.5, stock: 8 },
  { id: "potion", name: "Healing Potion", icon: "🧪", price: 12, stock: 5 },
  { id: "crystal", name: "Star Crystal", icon: "💎", price: 25, stock: 3 },
  { id: "cookie", name: "Pixel Cookie", icon: "🍪", price: 3, stock: 10 },
  { id: "plant", name: "Tiny Sprout", icon: "🌱", price: 8, stock: 4 }
];

let sales = 0;
const itemList = document.querySelector("#item-list");
const salesTotal = document.querySelector("#sales-total");
const money = amount => `$${amount.toFixed(2)}`;

function renderItems() {
  itemList.replaceChildren();
  for (const item of items) {
    const soldOut = item.stock === 0;
    const row = document.createElement("article");
    row.className = "item";

    const icon = document.createElement("div");
    icon.className = "item-icon";
    icon.setAttribute("aria-hidden", "true");
    icon.textContent = item.icon;

    const info = document.createElement("div");
    info.className = "item-info";
    const name = document.createElement("h3");
    name.className = "item-name";
    name.textContent = item.name;
    const meta = document.createElement("div");
    meta.className = "item-meta";
    const price = document.createElement("span");
    price.textContent = money(item.price);
    const stock = document.createElement("span");
    stock.className = soldOut ? "stock out" : "stock";
    stock.textContent = soldOut ? "Sold out" : `In stock: ${item.stock}`;
    meta.append(price, stock);
    info.append(name, meta);

    const actions = document.createElement("div");
    actions.className = "item-actions";
    const sell = document.createElement("button");
    sell.type = "button";
    sell.textContent = "Sell";
    sell.setAttribute("aria-label", `Sell ${item.name} for ${money(item.price)}`);
    sell.disabled = soldOut;
    sell.addEventListener("click", () => {
      if (item.stock === 0) return;
      item.stock -= 1;
      sales += item.price;
      salesTotal.textContent = money(sales);
      renderItems();
    });
    const restock = document.createElement("button");
    restock.type = "button";
    restock.className = "restock";
    restock.textContent = "Restock +10";
    restock.setAttribute("aria-label", `Restock ${item.name} by 10`);
    restock.addEventListener("click", () => {
      item.stock += 10;
      renderItems();
    });
    actions.append(sell, restock);
    row.append(icon, info, actions);
    itemList.append(row);
  }
}

renderItems();
